"""One visual, source-bound work session over the existing statement engine."""

WORKBENCH_CSS = r'''
.friday-workbench{display:grid;gap:20px;min-width:0}.work-ready{display:flex;justify-content:space-between;align-items:center;gap:16px}.work-ready h2{font-size:28px;letter-spacing:-.045em;margin:0 0 7px}.work-ready p{margin:0;font-size:12px;color:var(--muted)}.work-sequence{display:flex;gap:9px;flex-wrap:wrap;margin:0;padding:0;list-style:none}.work-sequence li{display:flex;align-items:center;gap:8px;font-size:12px;padding:11px 14px;border-radius:14px;background:var(--studio-mint)}.work-sequence li:last-child{background:var(--studio-lilac)}.work-sequence b{font-size:16px}.work-layout{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:16px;align-items:start}.work-chart,.work-task{border:1px solid var(--line);border-radius:24px;padding:22px;background:var(--panel);min-width:0}.work-chart h3,.work-task h3{font-size:20px;margin:0 0 12px;letter-spacing:-.03em}.work-chart-frame{position:relative;height:220px}.work-chart-total{display:flex;justify-content:space-between;gap:10px;font-size:12px;margin-top:17px}.work-chart-total strong{font-size:15px}.work-legend{display:grid;gap:10px;margin-top:18px}.work-legend>div{display:flex;align-items:center;gap:8px;font-size:12px}.work-legend i{width:9px;height:9px;border-radius:50%;flex:none}.work-legend strong{margin-left:auto;font-size:12px}.work-eyebrow{font-size:10px!important;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);margin:0 0 12px!important}.work-task{background:var(--studio-peach)}.work-task>p:not(.work-eyebrow){font-size:12px;line-height:1.7;color:var(--muted)}.work-source-row{display:grid;grid-template-columns:1fr auto;gap:8px;padding:14px;margin:8px 0;background:var(--panel);border:1px solid var(--line);border-radius:14px;font-size:12px}.work-source-row small{display:block;margin:5px 0 0;color:var(--muted);font-size:11px}.work-source-row b{font-size:15px;align-self:center;white-space:nowrap}.work-artifact{display:flex;align-items:center;gap:11px;margin:16px 0;padding:14px;background:var(--panel);border:1px solid var(--line);border-radius:16px;font-size:13px}.work-artifact svg{width:24px;height:24px;flex:none;color:var(--blue)}.work-artifact small{display:block;font-size:11px;color:var(--muted);margin-top:5px}.work-actions{display:flex;gap:9px;flex-wrap:wrap}.work-actions button{min-height:44px;padding:10px 14px;font-size:12px}.work-actions .run{width:auto;flex:1}.work-task details{margin-top:15px;font-size:12px}.work-task summary,.work-voice>summary{min-height:40px;display:flex;align-items:center;cursor:pointer;font-size:12px;color:var(--blue)}.work-task .checkup-draft{min-height:180px;background:var(--panel);margin-top:10px}.work-task .checkup-evidence{background:var(--panel);border-radius:12px}.work-status{font-size:12px;line-height:1.7;margin:12px 0 0;min-height:0}.work-status:empty{display:none}.work-more{display:flex;flex-wrap:wrap;gap:8px}.work-more button{font-size:12px;padding:10px 14px;min-height:44px}.work-boundary{margin:0;font-size:11px;color:var(--muted);line-height:1.7}.work-refund{padding:15px;background:var(--panel);border-radius:16px;margin-top:14px}.work-refund-head{display:flex;justify-content:space-between;gap:10px;font-size:12px;margin-bottom:12px}.work-refund .shield-range{margin:10px 0 6px}.work-refund small{font-size:11px;color:var(--muted)}.work-voice{border:1px solid var(--line);border-radius:17px;padding:4px 15px;background:var(--panel)}.work-voice p,.work-voice label{font-size:12px;line-height:1.6}.work-voice label{display:flex;align-items:start;gap:8px;margin:10px 0}.work-voice input{width:18px!important;flex:none}.work-voice audio{width:100%;margin-top:12px;display:block}.work-voice button{min-height:44px;font-size:12px;margin:5px 0 12px}.work-voice[aria-busy=true]{border-color:var(--blue)}
.friday-presence{display:grid;grid-template-columns:44px minmax(0,1fr) auto;gap:10px;align-items:center;padding:14px;border-radius:19px;background:var(--studio-mint);margin:0 0 16px}.friday-presence img{width:44px;height:44px;object-fit:contain;filter:drop-shadow(0 5px 7px #85857530)}.friday-presence b{display:block;font-size:12px;margin-bottom:5px}.friday-presence p{font-size:11px;line-height:1.6;margin:0;color:var(--muted)}.friday-presence button{font-size:11px;min-height:36px;padding:6px 9px;border-radius:12px;background:var(--panel);border:1px solid var(--line)}.friday-presence[data-state=working]{background:var(--studio-lilac)}.friday-presence[data-state=error]{background:var(--studio-peach)}.friday-presence[data-state=working] img{animation:friday-float 2.4s ease-in-out infinite}.friday-presence [role=status]{min-width:0}.work-mini{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px;background:var(--studio-mint);border:1px solid var(--line);border-radius:20px}.work-mini h2{font-size:20px;margin:0 0 7px}.work-mini p{font-size:12px;color:var(--muted);margin:0;line-height:1.6}.work-mini button{flex:none;width:auto;font-size:12px}
@media(max-width:1250px){.work-layout{grid-template-columns:1fr}.work-chart-frame{height:200px}.work-legend{grid-template-columns:1fr 1fr}.work-chart-total{margin-top:14px}}@media(max-width:950px) and (min-width:700px){.work-layout{grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr)}.work-legend{grid-template-columns:1fr}}@media(max-width:600px){.work-ready{align-items:flex-start}.work-ready h2{font-size:25px}.work-chart,.work-task{padding:18px}.work-sequence{gap:6px}.work-sequence li{font-size:10px;padding:10px;gap:5px}.work-sequence b{font-size:14px}.work-legend{grid-template-columns:1fr}.work-mini{display:block}.work-mini button{margin-top:14px}.work-source-row{font-size:11px;padding:12px}.work-source-row b{font-size:13px}.work-actions button{flex:1}.friday-presence{padding:12px;grid-template-columns:38px minmax(0,1fr) auto}.friday-presence img{width:38px;height:38px}}
@media(prefers-reduced-motion:reduce){.friday-presence img{animation:none!important}}html[data-motion=off] .friday-presence img{animation:none!important}
'''

WORKBENCH_JS = r'''
    {
      const graphs=new Map(),voicePlayers=new Map();let latest=null,reviewBusy=false,workEpoch=0;
      const cash=scenarioMoney,colors=['#b7a0ed','#f2aa8c','#8fc9ad','#e8c46e','#85bad2','#d2a2c7','#adb3d9','#c3ce96','#d9b69c','#9cc6ca','#b2a9bd'];
      const action=(text,fn,cls='planner')=>{const b=element('button',text,cls);b.type='button';b.addEventListener('click',fn);return b;};
      function stopAudio(){for(const [audio,url] of voicePlayers){audio.pause();audio.removeAttribute('src');URL.revokeObjectURL(url);}voicePlayers.clear();}
      function clearWork(){workEpoch++;latest=null;stopAudio();for(const c of graphs.values())c.destroy();graphs.clear();}
      for(const event of ['friday:cashflow-cleared','friday:portfolio-unavailable'])document.addEventListener(event,clearWork);
      document.addEventListener('friday:statements-updated',()=>{workEpoch++;stopAudio();});
      function voice(parent,data,valid){const d=element('details',null,'work-voice');d.append(element('summary','Hear my briefing · optional Google voice'));const consent=element('input');consent.type='checkbox';const label=element('label');label.append(consent,element('span','Send these statement totals to Google to create a temporary spoken briefing. No descriptions or microphone.'));const status=element('p','','work-status');status.setAttribute('role','status');const listen=action('Generate my briefing',async()=>{if(!consent.checked){status.textContent='Choose the sharing option first. Friday stays silent by default.';return;}if(!valid()){status.textContent='Reload My money before using this briefing.';return;}listen.disabled=true;consent.disabled=true;d.setAttribute('aria-busy','true');status.textContent='Creating your Google voice briefing…';const sent=workEpoch;try{const r=await jsonRequest('/api/friday/assistant/briefing-audio','POST',{expected_revision:data.revision,workspace_generation:data.workspace_generation,confirm_send_derived_totals_to_google:true});if(sent!==workEpoch||!valid())return;if(r.mime!=='audio/wav'||r.money_moved!==false||r.source_revision!==data.revision||r.workspace_generation!==data.workspace_generation||typeof r.audio_base64!=='string'||r.audio_base64.length>2000000)throw new Error('Invalid briefing');stopAudio();const bytes=Uint8Array.from(atob(r.audio_base64),c=>c.charCodeAt(0)),audio=element('audio');audio.controls=true;audio.preload='none';const url=URL.createObjectURL(new Blob([bytes],{type:r.mime}));audio.src=url;voicePlayers.set(audio,url);d.querySelector('audio')?.remove();d.append(audio);const transcript=element('details');transcript.append(element('summary','Read the spoken figures'),element('p',r.spoken_text));d.querySelector('.work-transcript')?.remove();transcript.className='work-transcript';d.append(transcript);status.textContent='Briefing ready. Press play when you want to listen.';}catch{if(sent===workEpoch)status.textContent='Google voice is unavailable. Your visual review still works; no audio result was assumed.';}finally{listen.disabled=false;consent.disabled=false;d.removeAttribute('aria-busy');}});d.append(label,listen,status);parent.append(d);}
      function evidence(parent,item){const d=element('details');d.append(element('summary','Show source evidence · '+item.evidence_count+' entries'));const wrap=element('div',null,'checkup-evidence'),table=element('table'),head=element('tr');['Date','Entry','Amount','Source'].forEach(t=>{const th=element('th',t);th.scope='col';head.append(th);});const thead=element('thead');thead.append(head);table.append(thead);const body=element('tbody');item.evidence.forEach(row=>{const tr=element('tr');[row.date,row.description,cash(row.debit_minor||row.credit_minor)+(row.debit_minor?' out':' in'),row.account_alias+' · row '+row.source_row].forEach(t=>tr.append(element('td',t)));body.append(tr);});table.append(body);wrap.append(table);d.append(wrap);parent.append(d);}
      function taskVisual(card,item,data){const f=data.checkup.findings.find(f=>f.finding_id===item.finding_id),trail=f?.trail_id&&data.checkup.money_shield?.trails.find(t=>t.trail_id===f.trail_id);if(trail){const box=element('div',null,'work-refund'),head=element('div',null,'work-refund-head');head.append(element('span','Recorded refund credits'),element('strong',cash(trail.refund_total_minor)));box.append(head);trail.purchases.slice(0,3).forEach(p=>{const row=element('div',null,'work-refund');row.append(element('span',p.evidence.date+' · purchase '+cash(p.evidence.debit_minor)));const range=element('div',null,'shield-range');range.setAttribute('aria-hidden','true');for(const value of [p.refund_max_minor,p.refund_min_minor]){const span=element('span');span.style.width=Math.min(100,value/p.evidence.debit_minor*100)+'%';range.append(span);}row.append(range,element('small','Possible return: '+cash(p.refund_min_minor)+(p.refund_min_minor===p.refund_max_minor?'':' – '+cash(p.refund_max_minor))));box.append(row);});box.append(element('small','Alternative links, not bank confirmation. Ranges cannot be added as a loss.'));card.append(box);return;}
        item.evidence.slice(0,3).forEach(row=>{const e=element('div',null,'work-source-row'),text=element('div',row.description);text.append(element('small',row.date+' · row '+row.source_row));e.append(text,element('b',cash(row.debit_minor||row.credit_minor)));card.append(e);});if(item.evidence.length>3)card.append(element('p','+'+(item.evidence.length-3)+' entries in the evidence.'));
      }
      root.renderAssistantWorkbench=function(parent,data,compact,options){
        const work=data.assistant_work;if(!work||work.scope!=='FRIDAY_ASSISTANT_WORK'||work.money_moved!==false||work.source_revision!==data.revision||work.workspace_generation!==data.workspace_generation){parent.append(element('p','The current work session is unavailable. Reload My money.','statement-error'));return;}
        if(latest&&(latest.revision!==data.revision||latest.workspace_generation!==data.workspace_generation)){workEpoch++;stopAudio();}latest=data;
        document.dispatchEvent(new CustomEvent('friday:work-ready',{detail:{transaction_count:work.transaction_count,prepared_count:work.prepared_count,open_count:work.open_count}}));
        if(compact){const box=element('section',null,'work-mini'),copy=element('div');copy.append(element('h2',work.open_count?'Your review is ready.':'You’re up to date with these checks.'),element('p',work.transaction_count+' entries checked · '+work.prepared_count+' private next steps prepared.'));box.append(copy,action('See what Friday did',()=>options.open('overview'),'run'));parent.append(box);return;}
        const box=element('section',null,'friday-workbench');box.setAttribute('aria-label','Friday workbench');parent.append(box);const heading=element('header',null,'work-ready'),copy=element('div');copy.append(element('h2','I’ve done the sorting.'),element('p',data.summary.period.start+' — '+data.summary.period.end));heading.append(copy);box.append(heading);const sequence=element('ol',null,'work-sequence');[[work.transaction_count,'entries read'],[work.checks_completed,'checks run'],[work.prepared_count,'steps prepared']].forEach(([value,label])=>{const li=element('li');li.append(element('b',String(value)),element('span',label));sequence.append(li);});box.append(sequence);
        const grid=element('div',null,'work-layout'),picture=element('section',null,'work-chart');picture.append(element('h3','Your money picture'));const categories=data.summary.categories,frame=element('div',null,'work-chart-frame'),canvas=element('canvas');canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Classified spending by category. Exact figures follow.');frame.append(canvas);picture.append(frame);const legend=element('div',null,'work-legend');categories.forEach((row,i)=>{const line=element('div'),dot=element('i');dot.style.background=colors[i%colors.length];line.append(dot,element('span',row.category),element('strong',cash(row.amount_minor)));legend.append(line);});picture.append(legend);for(const [label,value] of [['Identified income',data.summary.totals.identified_income_minor],['Classified spending',data.summary.totals.classified_spending_minor],['Recorded repayments',data.summary.totals.loan_repayments_minor+data.summary.totals.card_repayments_minor]]){const row=element('div',null,'work-chart-total');row.append(element('span',label),element('strong',cash(value)));picture.append(row);}grid.append(picture);
        const previous=graphs.get(compact?'mini':'main');if(previous)previous.destroy();graphs.delete(compact?'mini':'main');queueMicrotask(()=>{if(!canvas.isConnected||!categories.length||typeof Chart==='undefined'){frame.hidden=true;return;}const chart=new Chart(canvas,{type:'doughnut',data:{labels:categories.map(r=>r.category),datasets:[{data:categories.map(r=>r.amount_minor),backgroundColor:colors,borderWidth:0,hoverOffset:5}]},options:{responsive:true,maintainAspectRatio:false,cutout:'76%',animation:matchMedia('(prefers-reduced-motion:reduce)').matches||document.documentElement.dataset.motion==='off'?false:{duration:350},plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>c.label+': '+cash(c.raw)}}}}});graphs.set('main',chart);});
        const item=work.next_item,card=element('section',null,'work-task');if(item){const labels={REPEATED_ENTRY:['Compare these entries','Comparison worksheet ready'],UNCLEAR_CREDIT:['Identify this incoming money','Classification worksheet ready'],REFUND_AMBIGUITY:['Clarify this return','Unsent enquiry ready']};const [title,ready]=labels[item.kind]||[item.title,'Unsent enquiry ready'];card.append(element('p','NEXT UP · '+work.open_count+' TO REVIEW','work-eyebrow'),element('h3',title));taskVisual(card,item,data);const artifact=element('div',null,'work-artifact'),text=element('div',ready);text.append(element('small','Prepared privately · no financial action'));artifact.append(everydayIcon('file-text'),text);card.append(artifact);const status=element('p','','work-status');status.setAttribute('role','status');const buttons=element('div',null,'work-actions');const save=action('Save '+(item.kind==='REPEATED_ENTRY'||item.kind==='UNCLEAR_CREDIT'?'worksheet':'enquiry'),()=>{if(!options.isCurrent()){status.textContent='Statement history changed. Reload before downloading.';return;}const url=URL.createObjectURL(new Blob([item.artifact.content],{type:'text/plain;charset=utf-8'})),a=element('a');a.href=url;a.download=item.artifact.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Downloaded privately. Nothing was sent to a bank.';});const mark=action('Reviewed → next',async()=>{if(reviewBusy||!options.isCurrent())return;reviewBusy=true;mark.disabled=true;save.disabled=true;const sent=workEpoch;status.textContent='Saving your review; source rows stay unchanged…';try{const r=await jsonRequest('/api/friday/statements/findings/review','POST',{finding_id:item.finding_id,reviewed:true,expected_revision:data.revision,workspace_generation:data.workspace_generation});if(sent!==workEpoch||!options.isCurrent())return;document.dispatchEvent(new CustomEvent('friday:statements-updated'));options.replace(r);toast('Review saved. Friday prepared the next item.');}catch{status.textContent='Review was not confirmed. Reload My money before retrying.';}finally{reviewBusy=false;mark.disabled=false;save.disabled=false;}},'run');buttons.append(save,mark);card.append(buttons,status);const preview=element('details');preview.append(element('summary','Read the prepared '+(item.kind==='REPEATED_ENTRY'||item.kind==='UNCLEAR_CREDIT'?'worksheet':'enquiry')));const field=element('textarea',item.artifact.content,'checkup-draft');field.readOnly=true;field.setAttribute('aria-label','Prepared private document');preview.append(field);card.append(preview);evidence(card,item);card.append(element('p','Review acknowledges a candidate. It does not correct a charge, label a credit or confirm fraud.','work-boundary'));
        }else{card.append(element('p','REVIEW COMPLETE','work-eyebrow'),element('h3','Nothing else in this review queue.'),element('p','These checks found no remaining open candidates. This is not a guarantee that every transaction is legitimate.'),action('View review history',()=>options.open('findings')));}grid.append(card);box.append(grid);
        const more=element('nav',null,'work-more');more.setAttribute('aria-label','Statement detail views');[['transactions','All entries'],['regular','Payment patterns'],['findings','Review history']].forEach(([tab,title])=>more.append(action(title,()=>options.open(tab))));more.append(action('Friday, guide me · share totals',()=>options.ask('Use my current statement checkup to explain the first review candidate and the prepared next step. Do not claim a charge was corrected or money recovered.')));box.append(more);voice(box,data,options.isCurrent);const limits=element('details',null,'checkup-proof');limits.append(element('summary','Coverage & how this work was done'));const list=element('ul');[...data.summary.warnings,...data.checkup.limits].forEach(t=>list.append(element('li',t)));limits.append(element('p','Exact checks and private document preparation run automatically. Gemini reasons over the derived totals only when you choose to share them. No bank connection or live monitoring.'),list);box.append(limits);
      };
      const presence=element('section',null,'friday-presence');presence.setAttribute('aria-label','Friday’s in-app guide');const face=everydayImage('friday-orb','');face.alt='';const words=element('div'),name=element('b','Here with you.'),line=element('p','Add a statement. I’ll prepare your review as you go.');words.setAttribute('role','status');words.setAttribute('aria-live','polite');words.append(name,line);let paused=false,lastGuide=null;const pause=action('Pause',()=>{paused=!paused;pause.textContent=paused?'Resume':'Pause';pause.setAttribute('aria-pressed',String(paused));if(paused){name.textContent='Guide paused';line.textContent='Your work and chat still function normally.';}else if(lastGuide)guide(...lastGuide);});pause.setAttribute('aria-label','Pause in-app guide');pause.setAttribute('aria-pressed','false');presence.append(face,words,pause);everydayAssistant.insertBefore(presence,$('friday-chat-log'));
      function guide(title,copy,state='ready'){lastGuide=[title,copy,state];if(paused)return;name.textContent=title;line.textContent=copy;presence.dataset.state=state;}
      let lastWork=null;document.addEventListener('friday:work-ready',e=>{lastWork=e.detail;if(!['READING','SAVING'].includes(presence.dataset.phase))guide('Your review is ready.',e.detail.prepared_count+' private next steps prepared from '+e.detail.transaction_count+' entries.');});
      document.addEventListener('friday:statement-stage',e=>{const phase=e.detail.phase;presence.dataset.phase=phase;const states={READING:['Reading your statement','Nothing is saved yet. I’m waiting for the extraction result.','working'],PROPOSED:['Preview ready','Check the rows once; I’ll prepare the review after you save.'],SAVING:['Preparing your review','Saving your confirmed rows, then running the exact checks.','working'],SAVED:['Your review is ready','Charts, source comparisons and private next steps are prepared.'],ERROR:['Let’s check that','The step was not confirmed. Your earlier records stay unchanged.','error']};if(states[phase])guide(...states[phase]);});
      document.addEventListener('friday:chat-state',e=>{const states={THINKING:['Thinking with Gemini','I’m working on the context you chose to share.','working'],REPLIED:['Your reply is ready','Open the result or continue the conversation.'],ERROR:['Gemini did not reply','Your statements and exact checks are still available.','error']};if(states[e.detail.phase])guide(...states[e.detail.phase]);});
      for(const event of ['friday:cashflow-cleared','friday:portfolio-unavailable'])document.addEventListener(event,()=>{lastWork=null;guide('Waiting for current evidence','Earlier results are not being treated as current.');});
      const beforeCompanionShow=show;show=function(name,push=true){beforeCompanionShow(name,push);if(command.getAttribute('aria-busy')==='true')return;if(name==='statements')guide('One statement is enough to start','Choose the file and confirm processing. No bank login needed.');else if(name==='statement-review')guide('Your preview, your choice','Review the extracted rows before saving them privately.');else if(name==='dashboard'&&lastWork)guide('Your workbench is ready',lastWork.prepared_count+' next steps prepared. Start with the highlighted one.');else if(name==='coach')guide('I’m listening here','Ask a question. Choose the totals toggle for a personal answer.');};
    }
'''
